    "new" : "nou",
    "_%n engagement in {month}_::_%n engagement in {month}_" : ["%n interacció al {month}","%n interaccions al {month}"],
    "_%n follower in {month}_::_%n followers in {month}_" : ["%n seguidor al {month}","%n seguidors al {month}"],
